Running python3 -c '
import re, pathlib
base = pathlib.Path("/Volumes/JokerData/PhD/PhD Research Proposal - Nguyen Minh Hieu (2026) (v3)/Slide PPNCKH/Bai_tap_ve_nha/systematic_review_prisma/screening_46/text")
specs = {
    "C05": [1, 3, 4, 10, 11, 12],
    "C06": [1, 6, 13, 15, 20, 21],
    "C07": [1, 2, 7, 12, 13],
    "C08": [1, 2, 10, 31, 35, 36, 40],
    "C09": [1, 4, 5, 11, 12],
    "C10": [1, 4, 5, 12, 13],
}
for cid, pages in specs.items():
    txt = (base / f"{cid}.txt").read_text(encoding="utf-8", errors="replace")
    parts = re.split(r"=== PAGE (\d+) ===", txt)
    pmap = {int(parts[i]): parts[i+1] for i in range(1, len(parts), 2)}
    if not pmap:
        pmap = {i+1: p for i, p in enumerate(txt.split("\f"))}
    print(f"*** {cid} (pages_found={len(pmap)}) ***")
    for p in pages:
        content = pmap.get(p, "").strip()
        lines = [ln.strip() for ln in content.splitlines() if ln.strip()]
        print(f"--- {cid} p.{p} (lines={len(lines)}) ---")
        for ln in lines[:35]:
            print(ln)
        if len(lines) > 35:
            print("... [TAIL] ...")
            for ln in lines[-15:]:
                print(ln)
'

