def load_pages(cid):
    txt = (base / f"{cid}.txt").read_text(encoding="utf-8", errors="replace")
    parts = re.split(r"=== PDF PAGE (\d+) ===", txt)
    return {int(parts[i]): parts[i+1] for i in range(1, len(parts), 2)}

def norm_text(s):
    # Replace ligatures & typography quirks from PDF extraction for faithful verification
    for a, b in [
        ("\ufb01", "fi"), ("\ufb02", "fl"), ("\ufb00", "ff"), ("\ufb03", "ffi"), ("\ufb04", "ffl"),
        ("UA V", "UAV"), ("\u00a0", " "), ("\u2013", "-"), ("\u2014", "-"),
    ]:
        s = s.replace(a, b)
    # Collapse hyphenation across line breaks only when matching prose, while also testing with hyphen kept
    s = re.sub(r"\s+", " ", s).strip()
    return s

def quote_matches_page(quote, page_txt):
    qn = norm_text(quote)
    pn_keep_hyphen = norm_text(re.sub(r"-\s*\n\s*", "-", page_txt))
    pn_drop_hyphen = norm_text(re.sub(r"-\s*\n\s*", "", page_txt))
    # Also handle line-wrapped spaced hyphens or IEEE spacing quirks like "3m" or "1–15"
    return (qn in pn_keep_hyphen) or (qn in pn_drop_hyphen)

