        ("\ufb01", "fi"), ("\ufb02", "fl"), ("\ufb00", "ff"), ("\ufb03", "ffi"), ("\ufb04", "ffl"),
        ("UA V", "UAV"), ("RUV A", "RUVA"), ("L AYER-WISE", "LAYER-WISE"),
        ("\u00a0", " "), ("\u2013", "-"), ("\u2014", "-"), ("\u2019", "'"), ("\u2018", "'"),
    ]:
        s = s.replace(a, b)
    s = re.sub(r"\s+", " ", s).strip()
    return s

def norm_nospace(s):
    return re.sub(r"[\s\-]", "", norm_strict(s)).lower()

def verify_quote(q, page_txt):
    # First test strict word/space match (with hyphenation joined or kept)
    qs = norm_strict(q)
    p_keep = norm_strict(re.sub(r"-\s*\n\s*", "-", page_txt))
    p_drop = norm_strict(re.sub(r"-\s*\n\s*", "", page_txt))
    if qs in p_keep or qs in p_drop:
        return "EXACT_MATCH"
    # Second test character sequence match allowing PDF kerning whitespace differences (e.g. "over25", "N= 10", " ,")
    if norm_nospace(q) in norm_nospace(page_txt):
        return "KERNING_MATCH"
    return "MISMATCH"

